import{_ as a,o as d,c as l,a5 as e}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"物理：Rigidbody 与 Collider","description":"你给物体加了 Rigidbody 它就受重力掉落，但你知道刚体和碰撞体各自负责什么吗？读完这一篇，你能说清 Rigidbody 和 Collider 的分工、三种刚体类型，以及为什么\\"有碰撞体没刚体\\"的物体会穿模。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"unity/04-gameplay/chapter-01-physics-rigidbody-collider.md","filePath":"unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"}'),s={name:"unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"};function t(r,i,c,o,p,y){return d(),l("div",null,[...i[0]||(i[0]=[e(`<h1 id="物理-rigidbody-与-collider" tabindex="-1" data-src-line="2" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">物理：Rigidbody 与 Collider <a class="header-anchor" href="#物理-rigidbody-与-collider" aria-label="Permalink to &quot;物理：Rigidbody 与 Collider&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">你给物体加了 Rigidbody 它就受重力掉落，但你知道刚体和碰撞体各自负责什么吗？读完这一篇，你能说清 Rigidbody 和 Collider 的分工、三种刚体类型，以及为什么&quot;有碰撞体没刚体&quot;的物体会穿模。</p><h2 id="_1-物理系统的两个角色" tabindex="-1" data-src-line="6" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">1. 物理系统的两个角色 <a class="header-anchor" href="#_1-物理系统的两个角色" aria-label="Permalink to &quot;1. 物理系统的两个角色&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">Unity 的物理引擎负责模拟物体的运动、碰撞、重力。它由两类组件配合工作：</p><ul data-src-line="10" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><li data-src-line="10" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><strong>Rigidbody（刚体）</strong>：让物体<strong>参与物理模拟</strong>——受重力、受力、有速度、参与碰撞响应。</li><li data-src-line="11" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><strong>Collider（碰撞体）</strong>：定义物体的<strong>碰撞形状</strong>——一个盒子、球体、胶囊或网格，用来判断&quot;两个物体是否碰到&quot;。</li></ul><p data-src-line="13" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">打个比方：Collider 是物体的&quot;外形&quot;（碰撞时用这个形状判断），Rigidbody 是物体的&quot;物理身份&quot;（有了它才被物理引擎管理）。两者缺一不可。</p><h2 id="_2-三种物理身份" tabindex="-1" data-src-line="15" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">2. 三种物理身份 <a class="header-anchor" href="#_2-三种物理身份" aria-label="Permalink to &quot;2. 三种物理身份&quot;">​</a></h2><p data-src-line="17" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">一个物体在物理世界里的身份，取决于它有没有 Rigidbody、Rigidbody 是什么类型：</p><table tabindex="0"><thead data-src-line="19" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><tr data-src-line="19" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><th>类型</th><th>组合</th><th>行为</th></tr></thead><tbody data-src-line="21" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><tr data-src-line="21" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><td>静态碰撞体（Static）</td><td>只有 Collider，没有 Rigidbody</td><td>不动，但能挡住别人。适合地面、墙壁</td></tr><tr data-src-line="22" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><td>动态刚体（Dynamic）</td><td>Rigidbody（默认）+ Collider</td><td>受重力和力，能移动、能碰撞。适合角色、掉落的箱子</td></tr><tr data-src-line="23" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><td>运动学刚体（Kinematic）</td><td>Rigidbody（勾选 Is Kinematic）+ Collider</td><td>不受物理力，但能推动别人。适合移动平台、门</td></tr></tbody></table><p data-src-line="25" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">最常见的坑：<strong>给一个只有 Collider 没有 Rigidbody 的物体（静态碰撞体）加移动代码，它会穿模</strong>。因为静态碰撞体物理引擎认为它永远不动，你手动改它的 <code>Transform</code> 位置时，物理引擎不会同步，也不产生碰撞响应。要让它动，要么加 Rigidbody，要么把移动交给物理 API。</p><h2 id="_3-rigidbody-的常用操作" tabindex="-1" data-src-line="27" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">3. Rigidbody 的常用操作 <a class="header-anchor" href="#_3-rigidbody-的常用操作" aria-label="Permalink to &quot;3. Rigidbody 的常用操作&quot;">​</a></h2><p data-src-line="29" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">给物体加 Rigidbody 后，通过脚本控制它的运动：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Rigidbody</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GetComponent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Rigidbody</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rb.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AddForce</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Vector3.up </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ForceMode.Impulse);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 施加瞬时冲量（如跳跃）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rb.linearVelocity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Vector3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 直接设速度</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rb.useGravity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 关闭重力</span></span></code></pre></div><ul data-src-line="39" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><li data-src-line="39" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><code>AddForce</code>：施加力，<code>ForceMode.Impulse</code> 是瞬时冲量（适合跳跃、射击后坐力），<code>ForceMode.Force</code> 是持续力。</li><li data-src-line="40" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><code>linearVelocity</code>：Unity 6 的写法，旧版本叫 <code>velocity</code>。直接读或写速度。</li><li data-src-line="41" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><code>useGravity</code>：是否受重力。</li></ul><p data-src-line="43" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">这些操作要放在 <code>FixedUpdate</code> 里，原因见<a href="./../03-scene-core/chapter-04-frame-loop.html">时间与帧循环</a>。</p><h2 id="_4-collider-的形状" tabindex="-1" data-src-line="45" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">4. Collider 的形状 <a class="header-anchor" href="#_4-collider-的形状" aria-label="Permalink to &quot;4. Collider 的形状&quot;">​</a></h2><p data-src-line="47" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">Collider 有不同形状，选择原则是&quot;形状越贴近物体、越简单越好&quot;：</p><ul data-src-line="49" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><li data-src-line="49" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><strong>Box Collider</strong>：盒子，最常用，适合方形物体。</li><li data-src-line="50" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><strong>Sphere Collider</strong>：球体，适合球类。</li><li data-src-line="51" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><strong>Capsule Collider</strong>：胶囊，适合角色。</li><li data-src-line="52" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><strong>Mesh Collider</strong>：按网格形状，最精确但性能最差，一般只用于静态地形。</li></ul><p data-src-line="54" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">碰撞检测的精度取决于 Collider，而不是物体的可见模型。一个复杂的角色模型，碰撞体通常是一个简化胶囊，而不是模型本身的几千个面。</p><h2 id="_5-动手验证" tabindex="-1" data-src-line="56" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">5. 动手验证 <a class="header-anchor" href="#_5-动手验证" aria-label="Permalink to &quot;5. 动手验证&quot;">​</a></h2><ol data-src-line="58" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md"><li data-src-line="58" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">场景里建一个 Plane（平面，自带 Mesh Collider，静态）和一个 Cube。</li><li data-src-line="59" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">给 Cube 加 Rigidbody，运行——Cube 掉落到 Plane 上停住。</li><li data-src-line="60" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">移除 Cube 的 Rigidbody，运行——如果给 Cube 加了移动代码，它会穿过 Plane；没代码则静止。</li></ol><p data-src-line="62" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">对比第 2、3 步，理解 Rigidbody 是否参与物理的区别。</p><p data-src-line="64" data-src-file="unity/04-gameplay/chapter-01-physics-rigidbody-collider.md">下一步深入碰撞检测，学会在&quot;物体碰到&quot;和&quot;物体穿过&quot;时触发逻辑：<a href="./chapter-02-collision-triggers.html">碰撞检测与触发器</a>。</p>`,23)])])}const g=a(s,[["render",t]]);export{h as __pageData,g as default};
